// Bridge a delegate API — makeStream hands back stream + continuation together
final class LocationFeed: NSObject, CLLocationManagerDelegate {
  let stream: AsyncStream<CLLocation>
  private let continuation: AsyncStream<CLLocation>.Continuation
  private let manager = CLLocationManager()

  override init() {
    (stream, continuation) = AsyncStream.makeStream(
      of: CLLocation.self,
      bufferingPolicy: .bufferingNewest(1)   // never queue stale fixes
    )
    super.init()
    manager.delegate = self
    continuation.onTermination = { [manager] _ in manager.stopUpdatingLocation() }
    manager.startUpdatingLocation()
  }

  func locationManager(_ m: CLLocationManager, didUpdateLocations locs: [CLLocation]) {
    for l in locs { continuation.yield(l) }
  }

  deinit { continuation.finish() }             // otherwise `for await` hangs
}

// Consumer — cancelling the Task tears the stream down via onTermination
let feed = LocationFeed()
let task = Task {
  for await loc in feed.stream { update(loc) }
}

// AsyncThrowingStream is the same shape, plus yield(with:) and finish(throwing:)

// Sendable struct — inferred, nothing to write
struct User: Sendable { let id: Int; let name: String }

// Final class with let-only stored properties — never inferred: the
// conformance is written out, and the compiler checks it
final class Config: Sendable {
  let apiKey: String
  init(apiKey: String) { self.apiKey = apiKey }
}

// Shared mutable state — Mutex keeps the value unreachable without the lock
import Synchronization

final class Counter: Sendable {
  private let state = Mutex(0)               // Mutex is itself Sendable
  var value: Int { state.withLock { $0 } }
  func increment() { state.withLock { $0 += 1 } }
}

// The older escape hatch: you promise, the compiler does not check
final class LegacyCounter: @unchecked Sendable {
  private let lock = NSLock()
  private var _value = 0
  func increment() { lock.lock(); defer { lock.unlock() }; _value += 1 }
}

// Sendable closure — required by Task.detached and friends
func spawn(_ work: @Sendable @escaping () -> Void) {
  Task.detached { work() }
}

// ❌ Swift 6 error: a non-Sendable class cannot cross the boundary
// final class Mutable { var x = 0 }
// let m = Mutable()
// Task { m.x = 1 }        // 'Mutable' is not Sendable
//
// ✅ Region isolation: fine, because `m` is never used again after the handoff
// let m = Mutable()
// Task { m.x = 1 }        // sole owner transferred into the task

// `sending` spells the transfer out in an API signature
func consume(_ value: sending Mutable) async { /* takes ownership */ }

@MainActor
@Observable
final class SearchModel {
  var results: [SearchHit] = []
  private var task: Task<Void, Never>?

  func update(query: String) {
    task?.cancel()
    task = Task {                                    // inherits @MainActor
      // Task.sleep honours cancellation and throws CancellationError
      try? await Task.sleep(for: .milliseconds(300)) // debounce
      guard !Task.isCancelled else { return }

      do {
        let r = try await api.search(query)          // URLSession honours cancel
        try Task.checkCancellation()
        results = r
      } catch is CancellationError {
        // expected — a newer keystroke won the race
      } catch {
        show(error)
      }
    }
  }

  func show(_ error: Error) {}
  deinit { task?.cancel() }
}

// Long-running work with a cancellation hook
func download(url: URL) async throws -> Data {
  let session = URLSession(configuration: .default)
  let dataTask = session.dataTask(with: url)
  return try await withTaskCancellationHandler {
    try await withCheckedThrowingContinuation { cont in
      dataTask.resume()
      // wire the completion handler to cont.resume(with:)
    }
  } onCancel: {
    dataTask.cancel()   // synchronous and Sendable — runs on the canceller's thread
  }
}

// async let  — cancelling the parent cancels every child automatically.
// TaskGroup  — group.cancelAll() cancels the remaining children.
// Note: onCancel can run BEFORE the operation body starts. Handle that.

@MainActor
@Observable
final class ProfileModel {
  private(set) var name = ""
  private(set) var isLoading = false

  // Every member is isolated to the main actor, so no hop is needed to touch state
  func load(id: String) async {
    isLoading = true
    defer { isLoading = false }
    name = (try? await api.profile(id: id).name) ?? ""   // resumes on the main actor
  }

  // Opt one member out — it touches no isolated state
  nonisolated var debugName: String { "ProfileModel" }
}

// A Task created from main-actor code inherits that isolation
@MainActor
func refresh(_ model: ProfileModel) {
  Task { await model.load(id: "42") }            // stays on the main actor
  Task.detached { await model.load(id: "42") }   // inherits nothing; the await is the hop
}

// Hopping on from a nonisolated context
func report(_ text: String, to model: ProfileModel) async {
  await MainActor.run { model.log(text) }
}

// A framework callback that is documented as main-thread-only but not annotated:
// assumeIsolated asserts it synchronously instead of deferring like MainActor.run
final class Handler: NSObject, SomeLegacyDelegate {
  let model: ProfileModel
  init(model: ProfileModel) { self.model = model }

  nonisolated func legacyDidFinish() {
    MainActor.assumeIsolated { model.log("done") }   // traps if we are not on main
  }
}

// One-shot callback -> continuation. Resume exactly once, on every path.
func currentLocation() async throws -> CLLocation {
  try await withCheckedThrowingContinuation { cont in
    provider.requestOnce { result in
      cont.resume(with: result)   // twice traps; never leaves the caller suspended forever
    }
  }
}

// Cancellation is not automatic — wire it yourself
func fetch(_ url: URL) async throws -> Data {
  let box = TaskBox()
  return try await withTaskCancellationHandler {
    try await withCheckedThrowingContinuation { cont in
      box.store(legacyClient.download(url) { cont.resume(with: $0) })
    }
  } onCancel: {
    box.cancel()   // runs concurrently with the body: keep it tiny and thread-safe
  }
}

// Multi-shot delegate -> AsyncStream
@MainActor
final class LocationFeed: NSObject, CLLocationManagerDelegate {
  private let manager = CLLocationManager()
  private var continuation: AsyncStream<CLLocation>.Continuation?

  func locations() -> AsyncStream<CLLocation> {
    let (stream, cont) = AsyncStream.makeStream(of: CLLocation.self)
    continuation = cont
    cont.onTermination = { _ in Task { @MainActor in self.manager.stopUpdatingLocation() } }
    manager.delegate = self
    manager.startUpdatingLocation()
    return stream
  }

  func locationManager(_ m: CLLocationManager, didUpdateLocations l: [CLLocation]) {
    l.forEach { continuation?.yield($0) }
  }

  func locationManager(_ m: CLLocationManager, didFailWithError e: Error) {
    continuation?.finish()   // without finish, the consuming `for await` never ends
  }
}

// Blocks a cooperative-pool thread. One of these per core and the app is wedged.
func badBridge() -> Data {
  let sema = DispatchSemaphore(value: 0)
  var result = Data()
  Task { result = (try? await api.download()) ?? Data(); sema.signal() }
  sema.wait()   // the Task above may never get a thread to run on
  return result
}

// The fix is not a cleverer bridge — it is making the caller async
func goodBridge() async throws -> Data {
  try await api.download()
}

// A genuinely blocking C or legacy API belongs on its own thread,
// bridged back with a continuation instead of running on the cooperative pool
private let ioQueue = DispatchQueue(label: "legacy.io")

func readLegacyFile(_ path: String) async throws -> Data {
  try await withCheckedThrowingContinuation { cont in
    ioQueue.async { cont.resume(with: Result { try blockingRead(path) }) }
  }
}

