// An actor is tested by awaiting it like any other async API
@Test func cacheDeduplicatesInFlightRequests() async throws {
  let api = CountingAPI()
  let cache = ImageCache(api: api)
  async let first = cache.image(for: "x")
  async let second = cache.image(for: "x")
  _ = try await (first, second)
